import{_ as s,a0 as i,w as a,s as l,ao as d,I as r,x as n,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"20条Linux命令面试问答 | LCTT x X-CMD","titleTemplate":false,"description":"20条Linux命令面试问答 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"20条Linux命令面试问答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"20条Linux命令面试问答 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141223 20 Linux Commands Interview Questions & Answers","title":"20条Linux命令面试问答","tag":"201502","desc":""},"relativePath":"201502/20141223 20 Linux Commands Interview Questions & Answers.md","filePath":"[post].md"}'),u={name:"201502/20141223 20 Linux Commands Interview Questions & Answers.md"};function x(g,t,m,f,L,c){const p=i("Link");return a(),l("div",null,[t[13]||(t[13]=d(`<h1 id="_20条linux命令面试问答" tabindex="-1">20条Linux命令面试问答 <a class="header-anchor" href="#_20条linux命令面试问答" aria-label="Permalink to “20条Linux命令面试问答”">​</a></h1><p><strong>问:1 如何查看当前的Linux服务器的运行级别？</strong></p><p>答: ‘who -r’ 和 ‘runlevel’ 命令可以用来查看当前的Linux服务器的运行级别。</p><p><strong>问:2 如何查看Linux的默认网关？</strong></p><p>答: 用 “route -n” 和 “netstat -nr” 命令，我们可以查看默认网关。除了默认的网关信息，这两个命令还可以显示当前的路由表。</p><p><strong>问:3 如何在Linux上重建初始化内存盘镜像文件？</strong></p><p>答: 在CentOS 5.X / RHEL 5.X中，可以用mkinitrd命令来创建初始化内存盘文件，举例如下：</p><pre><code># mkinitrd -f -v /boot/initrd-$(uname -r).img $(uname -r)
</code></pre><p>如果你想要给特定的内核版本创建初始化内存盘，你就用所需的内核名替换掉 ‘uname -r’ 。</p><p>在CentOS 6.X / RHEL 6.X中，则用dracut命令来创建初始化内存盘文件，举例如下：</p><pre><code># dracut -f
</code></pre><p>以上命令能给当前的系统版本创建初始化内存盘，给特定的内核版本重建初始化内存盘文件则使用以下命令：</p><pre><code># dracut -f initramfs-2.x.xx-xx.el6.x86_64.img 2.x.xx-xx.el6.x86_64
</code></pre><p><strong>问:4 cpio命令是什么？</strong></p><p>答: cpio就是复制入和复制出的意思。cpio可以向一个归档文件（或单个文件）复制文件、列表，还可以从中提取文件。</p><p><strong>问:5 patch命令是什么？如何使用？</strong></p><p>答: 顾名思义，patch命令就是用来将修改（或补丁）写进文本文件里。patch命令通常是接收diff的输出并把文件的旧版本转换为新版本。举个例子，Linux内核源代码由百万行代码文件构成，所以无论何时，任何代码贡献者贡献出代码，只需发送改动的部分而不是整个源代码，然后接收者用patch命令将改动写进原始的源代码里。</p><p>创建一个diff文件给patch使用，</p><pre><code># diff -Naur old_file new_file &gt; diff_file
</code></pre><p>旧文件和新文件要么都是单个的文件要么都是包含文件的目录，-r参数支持目录树递归。</p><p>一旦diff文件创建好，我们就能在旧的文件上打上补丁，把它变成新文件：</p><pre><code># patch &lt; diff_file
</code></pre><p><strong>问:6 aspell有什么用 ?</strong></p><p>答: 顾名思义，aspell就是Linux操作系统上的一款交互式拼写检查器。aspell命令继任了更早的一个名为ispell的程序，并且作为一款免费替代品 ，最重要的是它非常好用。当aspell程序主要被其它一些需要拼写检查能力的程序所使用的时候，在命令行中作为一个独立运行的工具的它也能十分有效。</p><p><strong>问:7 如何从命令行查看域SPF记录？</strong></p><p>答: 我们可以用dig命令来查看域SPF记录。举例如下：</p><pre><code>linuxtechi@localhost:~$ dig -t TXT google.com
</code></pre><p><strong>问:8 如何识别Linux系统中指定文件(/etc/fstab)的关联包？</strong></p><p>答: # rpm -qf /etc/fstab</p><p>以上命令能列出提供“/etc/fstab”这个文件的包。</p><p><strong>问:9 哪条命令用来查看bond0的状态？</strong></p><p>答: cat /proc/net/bonding/bond0</p><p><strong>问:10 Linux系统中的/proc文件系统有什么用？</strong></p><p>答: /proc文件系统是一个基于内存的文件系统，其维护着关于当前正在运行的内核状态信息，其中包括CPU、内存、分区划分、I/O地址、直接内存访问通道和正在运行的进程。这个文件系统所代表的并不是各种实际存储信息的文件，它们指向的是内存里的信息。/proc文件系统是由系统自动维护的。</p><p><strong>问:11 如何在/usr目录下找出大小超过10MB的文件？</strong></p><p>答: # find /usr -size +10M</p><p><strong>问:12 如何在/home目录下找出120天之前被修改过的文件？</strong></p><p>答: # find /home -mtime +120</p><p><strong>问:13 如何在/var目录下找出90天之内未被访问过的文件？</strong></p><p>答: # find /var \\! -atime -90</p><p><strong>问:14 在整个目录树下查找文件“core”，如发现则无需提示直接删除它们。</strong></p><p>答: # find / -name core -exec rm {} ;</p><p><strong>问:15 strings命令有什么作用？</strong></p><p>答: strings命令用来提取和显示非文本文件中的文本字符串。（LCTT 译注：当用来分析你系统上莫名其妙出现的二进制程序时，可以从中找到可疑的文件访问，对于追查入侵有用处）</p><p><strong>问:16 tee 过滤器有什么作用 ?</strong></p><p>答: tee 过滤器用来向多个目标发送输出内容。如果用于管道的话，它可以将输出复制一份到一个文件，并复制另外一份到屏幕上（或一些其它程序）。</p><pre><code>linuxtechi@localhost:~$ ll /etc | nl | tee /tmp/ll.out
</code></pre><p>在以上例子中，从ll输出可以捕获到 /tmp/ll.out 文件中，并且同样在屏幕上显示了出来。</p><p><strong>问:17 export PS1 = ”$LOGNAME@<code>hostname</code>:$PWD: 这条命令是在做什么？</strong></p><p>答: 这条export命令会更改登录提示符来显示用户名、本机名和当前工作目录。</p><p><strong>问:18 ll | awk ‘{print $3,”owns”,$9}’ 这条命令是在做什么？</strong></p><p>答: 这条ll命令会显示这些文件的文件名和它们的拥有者。</p><p><strong>问:19 :Linux中的at命令有什么用？</strong></p><p>答: at命令用来安排一个程序在未来的做一次一次性执行。所有提交的任务都被放在 /var/spool/at 目录下并且到了执行时间的时候通过atd守护进程来执行。</p><p><strong>问:20 linux中lspci命令的作用是什么？</strong></p><p>答: lspci命令用来显示你的系统上PCI总线和附加设备的信息。指定-v，-vv或-vvv来获取越来越详细的输出，加上-r参数的话，命令的输出则会更具有易读性。</p><hr>`,57)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(p,{href:"http://www.linuxtechi.com/20-linux-commands-interview-questions-answers/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.linuxtechi.com/20-linux-commands-interview-questions-answers/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=n("作者：",-1)),e(p,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:o(()=>[...t[2]||(t[2]=[n("Pradeep Kumar",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),e(p,{href:"https://github.com/ZTinoZ"},{default:o(()=>[...t[3]||(t[3]=[n("ZTinoZ",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),e(p,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),e(p,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const v=s(u,[["render",x]]);export{C as __pageData,v as default};
